package dev.rodrigo.blegattlab;

import android.Manifest; import android.bluetooth.*; import android.bluetooth.le.*; import android.content.pm.PackageManager; import android.os.*; import android.widget.*; import androidx.activity.ComponentActivity; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.core.content.ContextCompat; import java.util.*;

public class MainActivity extends ComponentActivity {
 private TextView status; private ArrayAdapter<String> adapter; private final List<BluetoothDevice> devices=new ArrayList<>(); private final Set<String> addresses=new HashSet<>(); private BluetoothLeScanner scanner; private BluetoothGatt gatt;
 private final ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->startScan());
 private final ScanCallback scanCallback=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){BluetoothDevice d=result.getDevice();String a=d.getAddress();if(addresses.add(a)){devices.add(d);String n="Unknown";try{if(hasConnect()){String x=d.getName();if(x!=null)n=x;}}catch(SecurityException ignored){}adapter.add(n+"\n"+a+"   RSSI "+result.getRssi());}}@Override public void onScanFailed(int code){status.setText("Scan failed: "+code);}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);ListView list=findViewById(R.id.list);adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,new ArrayList<>());list.setAdapter(adapter);findViewById(R.id.scan).setOnClickListener(v->requestOrScan());findViewById(R.id.stop).setOnClickListener(v->stopScan());list.setOnItemClickListener((p,v,pos,id)->connect(devices.get(pos)));BluetoothManager m=getSystemService(BluetoothManager.class);BluetoothAdapter a=m==null?null:m.getAdapter();scanner=a==null?null:a.getBluetoothLeScanner();status.setText(scanner==null?"BLE unavailable":"Ready");}
 private boolean hasScan(){return Build.VERSION.SDK_INT<31||ContextCompat.checkSelfPermission(this,Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED;} private boolean hasConnect(){return Build.VERSION.SDK_INT<31||ContextCompat.checkSelfPermission(this,Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED;}
 private void requestOrScan(){if(Build.VERSION.SDK_INT>=31&&(!hasScan()||!hasConnect()))permissions.launch(new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT});else if(Build.VERSION.SDK_INT<31&&ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)permissions.launch(new String[]{Manifest.permission.ACCESS_FINE_LOCATION});else startScan();}
 private void startScan(){if(scanner==null||!hasScan()){status.setText("BLE scanner/permission unavailable");return;}addresses.clear();devices.clear();adapter.clear();try{scanner.startScan(scanCallback);status.setText("Scanning… tap a device to connect");}catch(SecurityException e){status.setText("Permission denied");}}
 private void stopScan(){if(scanner!=null&&hasScan())try{scanner.stopScan(scanCallback);}catch(SecurityException ignored){}status.setText("Scan stopped");}
 private void connect(BluetoothDevice d){stopScan();if(!hasConnect()){status.setText("Connect permission required");return;}closeGatt();try{gatt=d.connectGatt(this,false,new BluetoothGattCallback(){@Override public void onConnectionStateChange(BluetoothGatt g,int s,int state){if(state==BluetoothProfile.STATE_CONNECTED){runOnUiThread(()->status.setText("Connected; discovering services…"));try{g.discoverServices();}catch(SecurityException ignored){}}else if(state==BluetoothProfile.STATE_DISCONNECTED)runOnUiThread(()->status.setText("Disconnected"));}@Override public void onServicesDiscovered(BluetoothGatt g,int s){StringBuilder out=new StringBuilder("Services\n");for(BluetoothGattService service:g.getServices()){out.append(service.getUuid()).append('\n');for(BluetoothGattCharacteristic c:service.getCharacteristics())out.append("  • ").append(c.getUuid()).append(" props=").append(c.getProperties()).append('\n');}runOnUiThread(()->status.setText(out.toString()));}},BluetoothDevice.TRANSPORT_LE);}catch(SecurityException e){status.setText("Connect permission denied");}}
 private void closeGatt(){if(gatt!=null){try{if(hasConnect())gatt.disconnect();}catch(SecurityException ignored){}gatt.close();gatt=null;}}
 @Override protected void onDestroy(){stopScan();closeGatt();super.onDestroy();}
}